/**
 * A compact index of every SRD spell: what a choice or a definition is checked
 * against.
 *
 * Generated by `scripts/spell-index.mjs` from the parsed spell data. It exists
 * because the engine is pure — it cannot read a file or import JSON at runtime
 * — and character creation needs to check that a chosen spell exists, is on
 * the right class list, and is of the right level and school.
 *
 * Do not edit by hand. Re-run the script after `srd:ingest`.
 */

export interface SpellIndexEntry {
  readonly id: string;
  readonly name: string;
  /** 0 for a cantrip. */
  readonly level: number;
  readonly school: string;
  /** Lower-cased class slugs the spell appears on. */
  readonly classes: readonly string[];
  /** As the SRD prints it: `Action`, `Bonus Action`, `1 minute`. */
  readonly castingTime: string;
  readonly ritual: boolean;
  readonly concentration: boolean;
  /**
   * Whether the casting has each of the three components the book prints.
   *
   * The material list itself is prose and is not here: what a rule asks is
   * whether a component is present — SRD Slow's "a spell with a Somatic
   * component", SRD Silence's "a spell that includes a Verbal component".
   */
  readonly components: {
    readonly verbal: boolean;
    readonly somatic: boolean;
    readonly material: boolean;
  };
}

